// Benchmarks Qwen3-0.6B decode using EmitC-compiled VM module.
// The emitc module replaces the VM bytecode interpreter with native C code.
#define _GNU_SOURCE
#include <stdio.h>
#include <string.h>
#include <time.h>
#include "iree/runtime/api.h"
#include "qwen3_emitc_module.h"  // generated by iree_c_module

static double now_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000.0 + ts.tv_nsec / 1e6;
}

int main() {
    iree_runtime_instance_options_t opts;
    iree_runtime_instance_options_initialize(&opts);
    iree_runtime_instance_options_use_all_available_drivers(&opts);
    iree_runtime_instance_t* instance = NULL;
    IREE_CHECK_OK(iree_runtime_instance_create(
        &opts, iree_allocator_system(), &instance));

    iree_hal_device_t* device = NULL;
    IREE_CHECK_OK(iree_runtime_instance_try_create_default_device(
        instance, iree_make_cstring_view("cuda"), &device));

    fprintf(stderr, "[init] CUDA device ready\n");

    // Create EmitC module
    iree_vm_module_t* emitc = NULL;
    IREE_CHECK_OK(llm_inference_qwen_create(
        iree_runtime_instance_vm_instance(instance),
        iree_allocator_system(), &emitc));
    fprintf(stderr, "[init] EmitC module: %.*s (%d exports)\n",
        (int)iree_vm_module_name(emitc).size,
        iree_vm_module_name(emitc).data,
        (int)iree_vm_module_signature(emitc).export_function_count);

    iree_vm_module_release(emitc);
    iree_hal_device_release(device);
    iree_runtime_instance_release(instance);
    fprintf(stderr, "[done] EmitC module works with CUDA HAL\n");
    return 0;
}
